INSERT INTO GTM_DEMO.RAW_SFDC.CASES (ID, ACCOUNT_ID, CONTACT_ID, CASE_NUMBER, SUBJECT, DESCRIPTION, STATUS, PRIORITY, ORIGIN, CREATED_DATE, LAST_MODIFIED_DATE) VALUES
('500ORB000000001AAA', '001ORB000000001AAA', '003ORB000000001AAA', '00001001', 'Add second region to scheduling workspace', 'Customer asked how to add another regional workspace and share crew calendars.', 'Closed', 'Low', 'Email', '2026-10-23 09:00:00', '2026-10-23 09:00:00'),
('500ORB000000002AAA', '001ORB000000003AAA', '003ORB000000007AAA', '00001002', 'Question about Enterprise tier features', 'Finance team asked what audit trails, SSO and approval chains are included in the higher tier.', 'Working', 'Medium', 'Email', '2026-10-23 09:00:00', '2026-10-23 09:00:00'),
('500ORB000000003AAA', '001ORB000000003AAA', '003ORB000000007AAA', '00001003', 'Seat limit warning on finance workspace', 'Admin received a warning that the workspace is near its seat limit.', 'New', 'Low', 'Web', '2026-10-23 09:00:00', '2026-10-23 09:00:00'),
('500ORB000000004AAA', '001ORB000000004AAA', '003ORB000000010AAA', '00001004', 'Repeated sync failures with TMS integration', 'Shipment status updates from the TMS fail to sync several times a week; dispatch team re-keys data.', 'Escalated', 'High', 'Phone', '2026-10-23 09:00:00', '2026-10-23 09:00:00'),
('500ORB000000005AAA', '001ORB000000004AAA', '003ORB000000012AAA', '00001005', 'Dispatch dashboard latency', 'Dispatch dashboard took 20+ seconds to load during peak hours.', 'Closed', 'Medium', 'Web', '2026-10-23 09:00:00', '2026-10-23 09:00:00'),
('500ORB000000006AAA', '001ORB000000007AAA', '003ORB000000019AAA', '00001006', 'Plant 2 onboarding questions', 'Questions about cloning plant 1 workflows for the second plant.', 'New', 'Low', 'Email', '2026-10-23 09:00:00', '2026-10-23 09:00:00'),
('500ORB000000007AAA', '001ORB000000009AAA', '003ORB000000025AAA', '00001007', 'SSO configuration for new claims team', 'Needs SAML group mapping for a new claims team of 120 users.', 'Working', 'Medium', 'Email', '2026-10-23 09:00:00', '2026-10-23 09:00:00');
